// spec: specs/client-ordering.md §7 · кейс .qa/tests/client-ordering/co-23-cart-remove-no-flash.md
// seed: tests/seed.buyer.spec.ts
// #f5aa41 (עבר QA 21.10): после «הסרה מהעגלה» одной строки остальные строки и сумма остаются на экране — ни на одном кадре
// нет скелетов загрузки и «סה״כ משוער ₪0.00»; итог = сумма оставшихся строк. Удаление последнего товара — обычное пустое состояние.
// Кадры ловит MutationObserver; второй прогон — с задержкой ответов корзины 1.5 с (только задержка, данные не подменяются).
// Данные: 3 своих товара QA-AUTO-f5aa-<ts>-1/2/3 (₪1/₪2/₪3, по 2 шт. «ללא מקום»); заказ не оформляется; afterAll — корзина
// пустая, товары удалены. Корзина buyer общая → serial, @orders (не параллельно с cart-checkout / order-lifecycle).
import { test, expect, Page } from '@playwright/test';
import { auth, createStockedProduct, emptyCart, cleanup } from '../orders/_qa-order';

test.use({ storageState: auth('buyer') });
test.describe.configure({ mode: 'serial' });

const TS = Date.now().toString().slice(-7);
const ITEMS = [1, 2, 3].map((n) => ({ name: `QA-AUTO-f5aa-${TS}-${n}`, price: n, id: '' }));
const created: string[] = [];

type Frame = { total: string; skeletons: number; rows: number; empty: boolean };

const summary = (page: Page) => page.getByText('סה״כ משוער').locator('..');
const removeBtn = (page: Page, name: string) => page.getByRole('button', { name: `הסרה מהעגלה — ${name}` });

async function fillCart(page: Page) {
  await emptyCart(page);
  for (const it of ITEMS) {
    await page.goto(`/shop/p/${it.id}`);
    const added = page.waitForResponse((r) => r.url().includes('cart_set_item'));
    await page.getByRole('button', { name: /^הוסף לעגלה/ }).click();
    await added;
  }
  await page.goto('/shop/cart');
  for (const it of ITEMS) await expect(removeBtn(page, it.name)).toBeVisible({ timeout: 20_000 });
  await expect(summary(page)).toContainText('₪6.00');
}

/** Запись всех кадров корзины (сумма, число скелетов, число строк) с момента вызова. */
async function startRecording(page: Page) {
  await page.evaluate(() => {
    const w = window as unknown as { __frames: Frame[] };
    type Frame = { total: string; skeletons: number; rows: number; empty: boolean };
    w.__frames = [];
    const snap = () => {
      const label = [...document.querySelectorAll('body *')].find((e) => e.children.length === 0 && (e.textContent || '').trim() === 'סה״כ משוער');
      w.__frames.push({
        total: (label?.parentElement?.textContent || '').replace(/\s+/g, ' ').trim(),
        skeletons: document.querySelectorAll('main .animate-pulse, .animate-pulse').length,
        rows: document.querySelectorAll('button[aria-label^="הסרה מהעגלה"]').length,
        empty: /העגלה ריקה/.test(document.body.textContent || ''),
      });
    };
    snap();
    new MutationObserver(snap).observe(document.body, { childList: true, subtree: true, characterData: true, attributes: true });
  });
}

const frames = (page: Page) => page.evaluate(() => (window as unknown as { __frames: Frame[] }).__frames);

async function removeMiddleAndCheck(page: Page) {
  await startRecording(page);
  await removeBtn(page, ITEMS[1].name).click();
  await expect(removeBtn(page, ITEMS[1].name)).toHaveCount(0, { timeout: 20_000 });
  await expect(summary(page)).toContainText('₪4.00');
  await expect(removeBtn(page, ITEMS[0].name)).toBeVisible();
  await expect(removeBtn(page, ITEMS[2].name)).toBeVisible();
  const f = await frames(page);
  expect(f.length, 'кадры записаны').toBeGreaterThan(1);
  expect(f.filter((x) => !/₪\d/.test(x.total)), 'в каждом кадре сумма найдена').toEqual([]);
  expect(f.filter((x) => /₪0\.00/.test(x.total)), 'ни одного кадра «סה״כ משוער ₪0.00»').toEqual([]);
  expect(f.filter((x) => x.skeletons > 0), 'ни одного кадра со скелетами').toEqual([]);
  expect(f.filter((x) => x.rows < 2 || x.empty), 'строки не исчезают, нет пустой корзины').toEqual([]);
  await expect(page.getByText('2 פריטים', { exact: true }).first()).toBeVisible();
}

test.describe('client-ordering — הסרה מהעגלה בלי ₪0.00 ושלדי טעינה (#f5aa41)', () => {
  test.beforeAll(async ({ browser }) => {
    test.setTimeout(240_000);
    const ctx = await browser.newContext({ storageState: auth('admin'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    const page = await ctx.newPage();
    for (const it of ITEMS) {
      created.push(it.name);
      it.id = await createStockedProduct(page, it.name, `QAF5AA${TS}${it.price}`, it.price, 2);
    }
    await ctx.close();
  });

  test.afterAll(async ({ browser }) => {
    test.setTimeout(180_000);
    const ctx = await browser.newContext({ storageState: auth('buyer'), locale: 'he-IL' });
    await emptyCart(await ctx.newPage()).catch(() => {});
    await ctx.close();
    await cleanup(browser, [], created);
  });

  test('הסרת שורה מ-3: השורות והסכום נשארים, אין ₪0.00 ואין שלדים בשום פריים; הסכום הנכון ₪4.00 #f5aa41 @desktop @orders', async ({ page }) => {
    test.setTimeout(120_000);
    await fillCart(page);
    await removeMiddleAndCheck(page);
  });

  test('רשת איטית (תגובות העגלה +1.5 ש׳): אותו דבר — בלי מצב ביניים של עגלה ריקה #f5aa41 @desktop @orders', async ({ page }) => {
    test.setTimeout(120_000);
    await fillCart(page);
    await page.route(/supabase\.co\/rest\/v1\/(rpc\/cart_|cart_items)/, async (route) => {
      await new Promise((r) => setTimeout(r, 1500)); // эмуляция медленной сети, не пауза теста
      await route.continue();
    });
    await removeMiddleAndCheck(page);
    await page.unroute(/supabase\.co\/rest\/v1\/(rpc\/cart_|cart_items)/);
  });

  test('הסרת הפריטים האחרונים — מצב ריק רגיל («העגלה ריקה», «חזרה לקטלוג») #f5aa41 @desktop @orders', async ({ page }) => {
    test.setTimeout(120_000);
    await page.goto('/shop/cart');
    await expect(removeBtn(page, ITEMS[0].name)).toBeVisible({ timeout: 20_000 });
    await removeBtn(page, ITEMS[0].name).click();
    await expect(removeBtn(page, ITEMS[0].name)).toHaveCount(0, { timeout: 20_000 });
    await expect(summary(page)).toContainText('₪3.00');
    await removeBtn(page, ITEMS[2].name).click();
    await expect(page.getByText('העגלה ריקה')).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText('עדיין לא הוספת מוצרים. חזור לקטלוג כדי להתחיל הזמנה.')).toBeVisible();
    await expect(page.getByRole('button', { name: 'חזרה לקטלוג' }).last()).toBeVisible();
    await expect(page.locator('.animate-pulse')).toHaveCount(0);
  });
});
